begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end; $$;
insert into auth.users(id) values('28000700-0000-4000-8000-000000000001'),('28000700-0000-4000-8000-000000000002');
insert into public.user_roles(user_id,role) values('28000700-0000-4000-8000-000000000001','professional') on conflict do nothing;
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values('28000700-0000-4000-8000-000000000001','28000700-0000-4000-8000-000000000002','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('28000700-0000-4000-8000-000000000002','Plano','{"routines":[{"id":"m","name":"Segunda","ex":[{"id":"0025","sets":3,"reps":10}]},{"id":"w","name":"Quarta","ex":[{"id":"0025","sets":3,"reps":10}]},{"id":"f","name":"Sexta","ex":[{"id":"0025","sets":3,"reps":10}]}],"week":{"1":"m","3":"w","5":"f"}}',0);
select public.send_student_plan('28000700-0000-4000-8000-000000000002',1);
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000002',true);
select public.mark_professional_plan_update_day_seen((select l.id from public.athlete_plan_library l join public.program_assignments a on a.id=l.assignment_id join public.program_versions v on v.id=a.version_id where l.user_id=auth.uid() order by v.version_number desc limit 1),(select a.version_id from public.program_assignments a join public.program_versions v on v.id=a.version_id where a.student_user_id=auth.uid() order by v.version_number desc limit 1),'monday');
select public.mark_professional_plan_update_day_seen((select l.id from public.athlete_plan_library l join public.program_assignments a on a.id=l.assignment_id join public.program_versions v on v.id=a.version_id where l.user_id=auth.uid() order by v.version_number desc limit 1),(select a.version_id from public.program_assignments a join public.program_versions v on v.id=a.version_id where a.student_user_id=auth.uid() order by v.version_number desc limit 1),'wednesday');
create temporary table original_views as select day_key,seen_at from public.professional_plan_update_day_views where student_user_id=auth.uid();
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('28000700-0000-4000-8000-000000000002','Plano','{"routines":[{"id":"m","name":"Segunda","ex":[{"id":"0025","sets":4,"reps":10}]},{"id":"w","name":"Quarta","ex":[{"id":"0025","sets":3,"reps":10}]},{"id":"f","name":"Sexta","ex":[{"id":"0025","sets":4,"reps":10}]}],"week":{"1":"m","3":"w","5":"f"}}',1);
select public.send_student_plan('28000700-0000-4000-8000-000000000002',2);
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select v.version_number=2 from public.professional_plan_update_day_views d join public.program_versions v on v.id=d.seen_version_id where d.student_user_id=auth.uid() and d.day_key='wednesday'),'unchanged wednesday carries to version two');
select pg_temp.assert_true((select d.seen_at=o.seen_at from public.professional_plan_update_day_views d join original_views o using(day_key) where d.student_user_id=auth.uid() and d.day_key='wednesday'),'carry preserves the real view timestamp');
select public.mark_professional_plan_update_day_seen((select l.id from public.athlete_plan_library l join public.program_assignments a on a.id=l.assignment_id join public.program_versions v on v.id=a.version_id where l.user_id=auth.uid() order by v.version_number desc limit 1),(select a.version_id from public.program_assignments a join public.program_versions v on v.id=a.version_id where a.student_user_id=auth.uid() order by v.version_number desc limit 1),'monday');
select pg_temp.assert_true((select d.seen_at>=o.seen_at from public.professional_plan_update_day_views d join original_views o using(day_key) where d.student_user_id=auth.uid() and d.day_key='monday'),'viewing monday updates its view timestamp');
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('28000700-0000-4000-8000-000000000002','Plano','{"routines":[{"id":"m","name":"Segunda","ex":[{"id":"0025","sets":3,"reps":10}]},{"id":"w","name":"Quarta","ex":[{"id":"0025","sets":3,"reps":10}]},{"id":"f","name":"Sexta","ex":[{"id":"0025","sets":5,"reps":10}]}],"week":{"1":"m","3":"w","5":"f"}}',2);
select public.send_student_plan('28000700-0000-4000-8000-000000000002',3);
select set_config('request.jwt.claim.sub','28000700-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select i->'workout_updates' ? 'monday' and not(i->'workout_updates' ? 'wednesday') and i->'workout_updates' ? 'friday' from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'),'v12 marks monday from its v11 base while preserving independent days');
select pg_temp.assert_true((select (i->'workout_update_bases'->'monday'->'version'->'weekly_plan'->'monday'->0->>'sets')::int=4 from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'),'monday update base is the last individual view');
rollback;
